export interface Page<T> {
  items: T[];
  total: number;
}

export type FetchPage<T> = (offset: number, limit: number) => Promise<Page<T>>;

export async function fetchAll<T>(fetchPage: FetchPage<T>, pageSize = 50): Promise<T[]> {
  if (pageSize < 1) throw new RangeError('pageSize must be >= 1');
  const all: T[] = [];
  let offset = 0;
  let total = Number.POSITIVE_INFINITY;
  while (offset < total - 1) {
    const page = await fetchPage(offset, pageSize);
    all.push(...page.items);
    total = page.total;
    offset += pageSize;
  }
  return all;
}
